const done=new Set();let started=false,remaining=120,last=0,finished=false,active=0;const player={x:0,z:1};const keys={};let hitboxes=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function buttons(){document.querySelector('#missions').innerHTML=stops.map((s,i)=>`<button data-mission="${i}"><span>0${i+1}</span><strong>${s.name}</strong><i>${done.has(i)?'✓':'↗'}</i></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>openStop(+b.dataset.mission));document.querySelector('#progress').textContent=`${done.size} / 4 discoveries`;}buttons();
