function openStop(i){start();active=i;const s=stops[i];content.innerHTML=`<div class="tag">STOP 0${i+1} / 04 · ${done.has(i)?'DISCOVERED':'~ 20 SECONDS'}</div><h2>${s.title}</h2><p>${s.text}</p><div class="flow">${s.flow}</div><p class="question">${s.q}</p><div class="answers">${s.answers.map((a,k)=>`<button data-answer="${k}">${a}</button>`).join('')}</div><p class="feedback" aria-live="polite"></p><details><summary>Behind the build</summary><p>${s.note}</p></details>${i===3?'<p><a href="https://www.instagram.com/yawnic3/" target="_blank" rel="noopener noreferrer">Visit @yawnic3 ↗</a></p>':''}`;content.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const f=content.querySelector('.feedback');if(+b.dataset.answer!==s.correct){f.textContent='Almost! Try the other answer.';return}done.add(i);buttons();f.textContent='✓ You got it. Discovery collected!';content.querySelectorAll('[data-answer]').forEach(a=>a.disabled=true);const next=document.createElement('button');next.className='next';next.textContent=done.size===4?'Finish the adventure →':'Next stop →';next.onclick=()=>{if(done.size===4)complete();else openStop(stops.findIndex((_,k)=>!done.has(k)))};content.append(next)});if(!modal.open)modal.showModal()}
function complete(){finished=true;content.innerHTML=`<div class="tag">ALL FOUR DISCOVERIES COLLECTED</div><h2>Small world.<br>Now you know mine.</h2><p>I build tools that help people plan, help machines perceive, and turn complex documents into useful data. And I run @yawnic3 on Instagram.</p><div class="flow">✓ API integration & scheduling<br>✓ Synthetic data & perception<br>✓ Document automation & validation<br>✓ A creative side beyond engineering</div><p>You finished in ${Math.floor((120-remaining)/60)}m ${Math.floor((120-remaining)%60)}s. Thanks for exploring.</p><button class="next" id="roam">Keep exploring</button>`;document.querySelector('#roam').onclick=()=>modal.close()}
function help(){content.innerHTML='<div class="tag">READY IN TEN SECONDS</div><h2>Your two-minute adventure.</h2><p><b>1.</b> Click one of the four mission buttons.<br><b>2.</b> Read a short explanation and answer one easy question.<br><b>3.</b> Collect all four discoveries. You’re done!</p><div class="flow">Want to roam? Move with WASD or arrow keys. Walk near a building and press E, or click its label. On a phone, use the arrow buttons.</div><p>The timer is a gentle guide. You can keep playing if it reaches zero.</p><button class="next" id="begin">Let’s play →</button>';if(!modal.open)modal.showModal();document.querySelector('#begin').onclick=()=>{modal.close();openStop(0)}}document.querySelector('#help').onclick=help;document.querySelector('#close').onclick=()=>modal.close();modal.addEventListener('close',()=>Object.keys(keys).forEach(k=>keys[k]=false));window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='e'&&!modal.open){const i=stops.findIndex(s=>Math.hypot(s.x-player.x,s.z-player.z)<3);if(i>=0)openStop(i)}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));document.querySelectorAll('[data-dir]').forEach(b=>{const key={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[b.dataset.dir];b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);keys[key]=true;start()};b.onpointerup=b.onpointercancel=()=>keys[key]=false});
